{
  "requirement_definitions": [
    {
      "id": "DMSR-8123",
      "title": "Tracking Characterization Changes Between Data Releases",
      "text": "Small, overlapping, samples of data from older releases shall be kept loaded in the database."
    },
    {
      "id": "DMSR-4655",
      "title": "Produce Images for EPO",
      "text": "The DMS shall produce images for EPO purposes, according to the requirements in the DM-EPO ICD."
    },
    {
      "id": "DMSR-4180",
      "title": "All-Sky Visualization of Data Releases",
      "text": "Data Release Processing shall generate co-adds suitable for use in all-sky visualization tools, allowing panning and zooming of the entire data release."
    },
    {
      "id": "DMSR-1178",
      "title": "Produce All-Sky HiPS Map",
      "text": "Data Release Production shall include the production of an all-sky image map for the existing coadded image area in each ﬁlter band, and at least one pre-deﬁned all-sky color image map, following the IVOA HiPS Recommendation."
    },
    {
      "id": "DMSR-2018",
      "title": "HiPS Service",
      "text": "The Data Management system shall include a secure and authenticated Internet endpoint for an IVOA-compliant HiPS service. This service shall be advertised via Registry as well as in the HiPS community mechanism operated by CDS, or whatever equivalent mechanism may exist in the LSST operations era."
    },
    {
      "id": "DMSR-5840",
      "title": "HiPS Linkage to Coadds",
      "text": "The HiPS maps produced by the Data Management system shall provide for straightforward linkage from the HiPS data to the underlying LSST coadded images. This SHOULD be implemented using a mechanism supported by both the LSST Science Platform and by community tools."
    }
  ],
